mapper.select:
select b_id bId, alarm_id alarmId, name, grade, driver_id driverId, driver_name driverName, trip_id tripId, detail, result_process resultProcess, remark, community_id communityId
from business_pubcar_alarm
where b_id = #{bId} and operate = #{operate}

SELECT a.alarm_id alarmId, a.create_time alarmTime, a.`name`, a.grade, uu.`name` applicant,
       o.org_name department, td.name position, uu.tel, a.remark, a.detail, a.result_process resultProcess
FROM pubcar_alarm a
LEFT JOIN pubcar_trip t ON t.trip_id = a.trip_id AND t.status_cd = '0'
LEFT JOIN u_user uu ON uu.user_id = t.user_id AND uu.status_cd = '0'
LEFT JOIN u_org_staff_rel uosr ON uosr.staff_id = uu.user_id AND uosr.status_cd = '0'
LEFT JOIN t_dict td ON td.status_cd = uosr.rel_cd AND td.table_name = 'u_org_staff_rel' AND td.table_columns = 'rel_cd'
LEFT JOIN u_org o ON o.org_id = uosr.org_id AND o.status_cd = '0'
WHERE a.status_cd = '0'

    and a.grade= #{grade}


    and a.result_process is not null


    and a.result_process is null


    and a.result_process= #{resultProcess}


     and a.create_time >= #{lessAlarmTime}


     and a.create_time <= #{moreAlarmTime}


    and a.alarm_id= #{alarmId}


    and (a.community_id= #{communityId} or a.community_id='-1')

order by a.create_time desc

    limit #{page}, #{row}

